# ===== modules/data_bucket/variables.tf =====
variable "bucket_name"      { type = string }
variable "environment"      { type = string }
variable "expire_days"      { type = number  default = 90 }

# ===== modules/data_bucket/main.tf =====
resource "aws_s3_bucket" "this" {
  bucket = var.bucket_name
  tags   = { Environment = var.environment, ManagedBy = "terraform" }
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id
  versioning_configuration { status = "Enabled" }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id
  rule {
    apply_server_side_encryption_by_default { sse_algorithm = "aws:kms" }
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket                  = aws_s3_bucket.this.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  bucket = aws_s3_bucket.this.id
  rule {
    id     = "expire-old-objects"
    status = "Enabled"
    expiration { days = var.expire_days }
  }
}

resource "aws_iam_policy" "pipeline_access" {
  name = "${var.bucket_name}-pipeline-access"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ListBucket"
        Effect   = "Allow"
        Action   = ["s3:ListBucket"]
        Resource = [aws_s3_bucket.this.arn]
      },
      {
        Sid      = "ObjectRW"
        Effect   = "Allow"
        Action   = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject"]
        Resource = ["${aws_s3_bucket.this.arn}/*"]
      }
    ]
  })
}

# ===== modules/data_bucket/outputs.tf =====
output "bucket_name" { value = aws_s3_bucket.this.id }
output "bucket_arn"  { value = aws_s3_bucket.this.arn }
output "policy_arn"  { value = aws_iam_policy.pipeline_access.arn }

# ===== usage: environments/prod/main.tf =====
module "raw_bucket" {
  source      = "../../modules/data_bucket"
  bucket_name = "acme-raw-prod"
  environment = "prod"
  expire_days = 30
}

resource "aws_iam_role_policy_attachment" "pipeline" {
  role       = aws_iam_role.pipeline.name
  policy_arn = module.raw_bucket.policy_arn
}

